css:
@layer provenance;
@layer provenance.reset;
@layer provenance.tokens;
@layer provenance.recipes;
@layer provenance.utilities;
@layer provenance.overrides;
@layer provenance.tokens.base;
@layer provenance.tokens.axes;
@layer provenance.tokens.cases;
@layer provenance.tokens.base {
  :root {
    --provenance-space-sm: 8px;
    --provenance-space-md: 16px;
    --provenance-color-ink: oklch(0.2 0.02 265);
  }
}
@layer provenance.recipes {
  .vanity\.testing_row__lc0c100 {
    color: var(--provenance-color-ink);
    padding: var(--provenance-space-sm);
  }
  .vanity\.testing_row_size_large__lc0c101 {
    padding: var(--provenance-space-md);
  }
  .vanity\.testing_empty__lc0c102 {
    display: block;
  }
  .vanity\.testing_anatomyRow_root__lc0c103 {
    display: grid;
    gap: var(--provenance-space-sm);
  }
  .vanity\.testing_anatomyRow_label__lc0c104 {
    color: var(--provenance-color-ink);
  }
  .vanity\.testing_anatomyRow_density_comfy_root__lc0c105 {
    gap: var(--provenance-space-md);
  }
  .vanity\.testing_compound__lc0c106 {
    display: block;
  }
  .vanity\.testing_compound_active__lc0c107 {
    opacity: 0.5;
  }
  .vanity\.testing_compound_compound_0__lc0c108 {
    color: var(--provenance-color-ink);
  }
}
